import os, pty, sys, select, time
def run(cwd, args, answers, timeout=20, cols=100, rows=40, idle=1.0, exe='/workspace/executable'):
    pid, fd = pty.fork()
    if pid == 0:
        os.chdir(cwd)
        os.environ['TERM']='xterm-256color'
        os.execv(exe, ['zk']+args)
    import fcntl, termios, struct
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out=b''; ai=0; t0=time.time(); pending=b''; last=time.time()
    while time.time()-t0 < timeout:
        r,_,_=select.select([fd],[],[],0.1)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d; pending+=d; last=time.time()
            while b'\x1b[6n' in pending:
                pending=pending.replace(b'\x1b[6n',b'',1)
                os.write(fd,b'\x1b[%d;1R'%rows)
            continue
        if time.time()-last < idle: continue
        if ai < len(answers):
            os.write(fd, answers[ai]); ai+=1; last=time.time()
        else:
            break
    time.sleep(0.5)
    while True:
        r,_,_=select.select([fd],[],[],0.5)
        if not r: break
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    st=0
    try: _,st=os.waitpid(pid,os.WNOHANG)
    except Exception: pass
    try: os.close(fd)
    except Exception: pass
    try:
        _,st=os.waitpid(pid,0)
    except Exception: pass
    return out, st
if __name__=='__main__':
    cwd=sys.argv[1]; args=[]; answers=[]; mode='a'
    for a in sys.argv[2:]:
        if a=='--IN': mode='i'; continue
        if mode=='a': args.append(a)
        else: answers.append(a.encode().decode('unicode_escape').encode('latin1'))
    o,st=run(cwd,args,answers)
    sys.stdout.buffer.write(o)
    sys.stderr.write("\n[[EXITSTATUS=%d code=%d]]\n"%(st, st>>8))
EOF
